    assert.equal(message.to, 'ana@example.com');
    assert.ok(message.body.includes('mudei de ideia'));
    assert.ok(message.body.includes('estornado'));
    assert.equal(salesReport(store.orders.listOrders()).orderCount, 1);
    assert.equal(salesReport(store.orders.listOrders()).bySku['TEC-040'], undefined);
    assert.equal(kept.status, 'pending');
  });
});
